        [-9, -9, -9, -9, -9, -9, 9, -9, -9, -9],
        [-9, -9, -9, -9, -9, -9, -9, 9, -9, -9],
        [-9, -9, -9, -9, -9, -9, -9, -9, 9, -9],
        [-9, -9, -9, -9, -9, -9, -9, -9, -9, 9]
      ],
      "temp": [9]
    },
    "cannot_express": true,
    "rationale": "Attempt lowers retention while preserving sharp colour associations. Moving the red object toward the cyan square requires different outputs for different input-zero pixels; this template outputs the same colour for every pixel of a given input colour."
  },
  {
    "task_id": "b7fb29bc",
    "params": {
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0],
      "conn": [0, 9]
    },
    "cannot_express": true,
    "rationale": "Attempt uses eight-connected enclosure. The required interior contains both 4 and 2 in a marker-dependent pattern, whereas this template fills every enclosed background pixel with one learned colour."
  },
  {
    "task_id": "84db8fc4",
    "params": {
